import{_ as a,c as t,o,ao as i}from"./chunks/framework.DAsozCiY.js";const u=JSON.parse('{"title":"Statement on User Right to Be Informed for Pogget","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/pogget-service.md","filePath":"en/agreement/pogget-service.md"}'),n={name:"en/agreement/pogget-service.md"};function r(s,e,c,l,d,h){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="statement-on-user-right-to-be-informed-for-pogget" tabindex="-1">Statement on User Right to Be Informed for Pogget <a class="header-anchor" href="#statement-on-user-right-to-be-informed-for-pogget" aria-label="Permalink to &quot;Statement on User Right to Be Informed for Pogget&quot;">​</a></h1><p>To safeguard your right to be informed while using Pogget (hereinafter referred to as the “Application”) and to clearly define the scope of data processing that may be involved when Vilinko (hereinafter referred to as “we” or “us”) provides services, this statement is formulated in accordance with the Service Terms and the Privacy Policy.</p><h2 id="_1-description-of-user-rights" tabindex="-1">1. Description of User Rights <a class="header-anchor" href="#_1-description-of-user-rights" aria-label="Permalink to &quot;1. Description of User Rights&quot;">​</a></h2><h3 id="_1-1-personal-use-license" tabindex="-1">1.1 Personal Use License <a class="header-anchor" href="#_1-1-personal-use-license" aria-label="Permalink to &quot;1.1 Personal Use License&quot;">​</a></h3><p>We grant you a personal, non-transferable, and non-exclusive license to use the Application and its related features solely for non-commercial purposes such as personal learning, research, and entertainment.<br> If you intend to use the Application in a commercial environment, you must contact us in advance to obtain formal written authorization. For any unauthorized commercial use, we reserve the right to pursue legal liability in accordance with applicable laws and regulations.</p><h3 id="_1-2-non-commercial-sharing-authorization" tabindex="-1">1.2 Non-Commercial Sharing Authorization <a class="header-anchor" href="#_1-2-non-commercial-sharing-authorization" aria-label="Permalink to &quot;1.2 Non-Commercial Sharing Authorization&quot;">​</a></h3><p>Provided that the Application content remains complete and copyright information is clearly displayed, you may share the Application through third-party platforms or channels for non-commercial purposes.</p><h3 id="_1-3-authorization-for-derivative-content-creation" tabindex="-1">1.3 Authorization for Derivative Content Creation <a class="header-anchor" href="#_1-3-authorization-for-derivative-content-creation" aria-label="Permalink to &quot;1.3 Authorization for Derivative Content Creation&quot;">​</a></h3><p>We support lawful secondary creation based on the Application, including but not limited to producing videos, writing articles, or publishing blog posts. Any revenue sharing obtained by you through such creative activities belongs solely to you.<br> If your creation involves brand collaborations, offline publication, or other commercial uses, you must contact us in advance and obtain written authorization.</p><h2 id="_2-description-of-data-processing" tabindex="-1">2. Description of Data Processing <a class="header-anchor" href="#_2-description-of-data-processing" aria-label="Permalink to &quot;2. Description of Data Processing&quot;">​</a></h2><p>We attach great importance to the protection of user privacy and consistently adhere to the principle of “minimum necessity” in all data processing activities.</p><h3 id="_2-1-scope-of-data-access" tabindex="-1">2.1 Scope of Data Access <a class="header-anchor" href="#_2-1-scope-of-data-access" aria-label="Permalink to &quot;2.1 Scope of Data Access&quot;">​</a></h3><ul><li>(1) User-initiated authorization: When you actively add files or data within the Application, this shall be deemed as your authorization for us to access the relevant content;</li><li>(2) Project interoperability support: To enable functional linkage, the Application may, when necessary, access interoperable data generated by other Vilinko projects;</li><li>(3) Access restrictions: Except for the circumstances described above, the Application will not access or read other private files on your device, photo albums, or data from third-party applications.</li></ul><h3 id="_2-2-storage-of-runtime-information" tabindex="-1">2.2 Storage of Runtime Information <a class="header-anchor" href="#_2-2-storage-of-runtime-information" aria-label="Permalink to &quot;2.2 Storage of Runtime Information&quot;">​</a></h3><p>To ensure proper operation of the Application and to provide a personalized experience, the Application will read and write necessary runtime configuration and cache information, including but not limited to:</p><ul><li>(1) Application status records, such as first-launch indicators and current version numbers;</li><li>(2) Interface configuration information, such as layout settings, user-defined preferences, and UI states;</li><li>(3) Performance optimization data, such as temporary cache files.<br> The above information is used solely to maintain application functionality and does not involve your personal sensitive information.</li></ul><h3 id="_2-3-network-connectivity-and-data-usage" tabindex="-1">2.3 Network Connectivity and Data Usage <a class="header-anchor" href="#_2-3-network-connectivity-and-data-usage" aria-label="Permalink to &quot;2.3 Network Connectivity and Data Usage&quot;">​</a></h3><p>The Application establishes network connections only under the following circumstances:</p><ul><li>(1) Version update checks to obtain the latest version information;</li><li>(2) Basic information services, such as viewing official announcements, developer information, and sponsor details;</li><li>(3) Diagnostic and analytical support: with your explicit authorization, we may collect fault-related runtime information to optimize product performance.</li></ul><p>Except for the explicitly stated scenarios above, the Application will not collect, upload, or synchronize any of your data over the network. All your files and information are stored locally on your device.<br> As data is not automatically synchronized to the cloud, you are advised to properly manage and back up important data to avoid irreversible loss caused by misoperation or data cleanup.</p>',20)]))}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
